 }

 .hero__inner {
   display: flex;
   flex-direction: column;
   align-items: center;
   gap: 24px;
 }

 .hero__title {
-  max-width: 16ch;
+  max-width: 20ch;
+  text-wrap: balance;
   font-size: clamp(2.75rem, 7.5vw, 6rem);
   font-weight: 600;
   letter-spacing: -0.04em;
   line-height: 0.98;
 }

 .hero__sub {
