   border-radius: var(--r-lg);
   background: var(--surface);
 }

 .beat__quote {
   font-size: 1.125rem;
   font-weight: 600;
   letter-spacing: -0.01em;
   line-height: 1.35;
 }

 .beat__support {
   color: var(--muted);
   font-size: 0.9375rem;
