 /* ---------------------------------------------------------------- */

 .tool {
   display: flex;
   flex-direction: column;
   gap: 8px;
   padding: 18px 20px;
   border: 1px solid var(--line);
   border-radius: var(--r-md);
   background: var(--surface);
 }

 .tool__name {
   font-family: var(--mono);
   font-size: 0.875rem;
   font-weight: 600;
   color: var(--accent);
 }

 .tool__purpose {
   color: var(--muted);
   font-size: 0.875rem;
   line-height: 1.55;
 }

 .tool__sig {
   font-family: var(--mono);
   font-size: 0.75rem;
   color: var(--faint);
   overflow-wrap: anywhere;
 }

 /* ---------------------------------------------------------------- */
 /* Status                                                           */
 /* ---------------------------------------------------------------- */

 .status-grid {
   display: grid;
   gap: 20px;
   grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 }

 .status-list {
   display: flex;
   flex-direction: column;
   gap: 12px;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .status-list li {
   display: flex;
   align-items: baseline;
   gap: 10px;
   color: var(--muted);
   font-size: 0.9375rem;
   line-height: 1.55;
 }

 .status-list li::before {
